{% extends "base_template.html" %}

{# 统一的页眉 LOGO 渲染宏：优先用 logo_base64，否则显示基准行文字标 #}
{% macro header_logo() -%}
{% if logo_base64 %}
<img class="logo-small" src="data:image/png;base64,{{ logo_base64 }}" alt="LOGO"/>
{% else %}
<span class="logo-small-text" style="display:inline-block; height:26px; line-height:26px; padding:0 10px; background:var(--primary); color:#fff; font-weight:700; font-size:11pt; letter-spacing:1px; border-radius:3px; font-family:'STSongti-SC-Bold','Noto Serif SC','SimSun',serif;">{{ ctx.meta.base_bank | default('基准行') }}</span>
{% endif %}
{%- endmacro %}

{% block content %}
{# ========================================================================
   3. Executive Summary
   ======================================================================== #}
<section class="page content first-content">
  <div class="page-header">
    {{ header_logo() }}
    <div class="header-text">执行摘要 · {{ ctx.meta.title }}</div>
  </div>

  <h2 class="section-title">执行摘要</h2>

  <p class="muted" style="margin-bottom:3mm">本报告基于 Skill 1 标准指标与 Skill 2 文字指标，
  为头部股份制银行 2024/2025 两期建立对标数据库，按 5 维度矩阵展开同业比较，
  以 <b>{{ ctx.meta.base_bank }}</b> 为基准行，输出 {{ ctx.ranking.metrics | length }} 项排名追踪与差距变化预警。</p>

  <div class="kpi-row skill4-kpi">
    {% for k in ctx.kpi_cards %}
    <div class="kpi-card">
      <div class="label">{{ k.label }}</div>
      <div class="value">{{ k.value }}{% if k.unit and k.unit != '—' %}<span class="unit">{{ k.unit }}</span>{% endif %}</div>
      <div class="yoy">同比 {{ k.yoy }}</div>
    </div>
    {% endfor %}
  </div>

  <div class="executive-summary">
    <h3>核心结论（{{ ctx.executive_summary | length }} 条）</h3>
    <ol>
      {% for s in ctx.executive_summary %}
      <li>{{ s | safe }}</li>
      {% endfor %}
    </ol>
  </div>

  <div class="two-col" style="margin-top:4mm">
    <div class="col-card win">
      <h4>★ 正向信号 · {{ ctx.ranking.positive_signals | length }} 条</h4>
      {% if ctx.ranking.positive_signals %}
      <ul style="margin:0;padding-left:5mm;font-size:8.5pt;line-height:1.7">
        {% for s in ctx.ranking.positive_signals %}
        <li>{{ s | rich_text }}</li>
        {% endfor %}
      </ul>
      {% else %}
      <p class="muted">本期暂无"差距缩小 / 领先扩大"的显著信号；多数指标受口径披露差异限制，
      同业可比窗口较窄，详见第五部分逐指标排名。</p>
      {% endif %}
    </div>
    <div class="col-card gap">
      <h4>⚠️ 负向信号 · {{ ctx.ranking.negative_signals | length }} 条</h4>
      {% if ctx.ranking.negative_signals %}
      <ul style="margin:0;padding-left:5mm;font-size:8.5pt;line-height:1.7">
        {% for s in ctx.ranking.negative_signals %}
        <li>{{ s | rich_text }}</li>
        {% endfor %}
      </ul>
      {% else %}
      <p class="muted">本期暂无"差距扩大 / 领先收窄"的显著信号；整体排名变化平稳，
      详见第五部分逐指标排名与前后名差距分析。</p>
      {% endif %}
    </div>
  </div>
</section>


{# ========================================================================
   4-7. 维度一 ~ 维度四（统一渲染宏）
   ======================================================================== #}
{% macro render_dimension(dim, part_no, part_label) %}
<section class="page content dimension-block">
  <div class="page-header">
    {{ header_logo() }}
    <div class="header-text">{{ part_label }} · {{ ctx.meta.title }}</div>
  </div>

  <h2 class="section-title">{{ part_label }} · {{ dim.title }}</h2>

  {% if dim.qualitative.formulas %}
  <div class="formula-list">
    <h4>计算公式</h4>
    <ul>
      {% for f in dim.qualitative.formulas %}
      <li>{{ f | safe }}</li>
      {% endfor %}
    </ul>
  </div>
  {% endif %}

  {% if dim.qualitative.opex_risk_text %}
  <div class="insight-card risk opex-risk">
    <h4>⚠️ 关键口径风险</h4>
    <p>{{ dim.qualitative.opex_risk_text | safe }}</p>
  </div>
  {% endif %}

  <h3 class="subsection-title">{{ dim.rows_2025 | length }} 家银行 2025 年横截面</h3>
  <table class="landscape-table">
    <thead>
      <tr>
        <th style="width:18%">银行</th>
        {% for col in dim.columns %}
        <th>{{ col }}</th>
        {% endfor %}
      </tr>
    </thead>
    <tbody>
      {% for row in dim.rows_2025 %}
      <tr {% if row.is_base %}class="row-highlight"{% endif %}>
        <td class="strong-col">{{ row.bank }}{% if row.is_base %} <span class="accent">★</span>{% endif %}</td>
        {% for col in dim.columns %}
          {% set val = row[dim.col_keys[loop.index0]] %}
          {% if val is none %}
            <td class="missing" style="text-align:center">—</td>
          {% elif '(%)' in col %}
            <td style="text-align:right">{{ "%.2f"|format(val) }}%</td>
          {% elif '(pp)' in col %}
            <td style="text-align:right">{{ "%.2f"|format(val) }}pp</td>
          {% else %}
            <td style="text-align:right">{{ "{:,.2f}".format(val) }}</td>
          {% endif %}
        {% endfor %}
      </tr>
      {% endfor %}
    </tbody>
  </table>

  {% if dim.yoy_changes %}
  <div class="yoy-list">
    <h4>2025 vs 2024 同比变化（按"{{ dim.yoy_label }}"）</h4>
    <ul>
      {% for c in dim.yoy_changes %}
      <li {% if c.is_base %}class="base-row"{% endif %}>
        {{ c.bank }}{% if c.is_base %} ★{% endif %}：
        {% if c.missing %}
          数据不完整（2024 = {% if c.v_2024_raw is none %}—{% else %}{{ c.v_2024_raw }}{% endif %}，2025 = {% if c.v_2025_raw is none %}—{% else %}{{ c.v_2025_raw }}{% endif %}）
        {% elif '(%)' in dim.yoy_field %}
          {{ "%.2f"|format(c.v_2025) }}% ← 2024 {{ "%.2f"|format(c.v_2024) }}% · 变化 {{ c.change_str }}
        {% elif '(pp)' in dim.yoy_field %}
          {{ "%.2f"|format(c.v_2025) }}pp ← 2024 {{ "%.2f"|format(c.v_2024) }}pp · 变化 {{ c.change_str }}
        {% else %}
          {{ "{:,}".format(c.v_2025 | int) }} ← 2024 {{ "{:,}".format(c.v_2024 | int) }} · 变化 {{ c.change_str }}
        {% endif %}
      </li>
      {% endfor %}
    </ul>
  </div>
  {% endif %}

  {% if dim.qualitative.calibration_notes %}
  <div class="callout-box">
    <h4 style="margin:0 0 1.5mm 0;color:var(--accent);font-size:9pt">口径提示</h4>
    <ul>
      {% for n in dim.qualitative.calibration_notes %}
      <li>{{ n | safe }}</li>
      {% endfor %}
    </ul>
  </div>
  {% endif %}

  {% if dim.qualitative.key_observations %}
  <div class="callout-box" style="border-left-color:var(--risk-red)">
    <h4 style="margin:0 0 1.5mm 0;color:var(--risk-red);font-size:9pt">关键观察</h4>
    <ul>
      {% for n in dim.qualitative.key_observations %}
      <li>{{ n | safe }}</li>
      {% endfor %}
    </ul>
  </div>
  {% endif %}

